import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.CxkNbRKf.js";const i="/nada-documentation/images/nada3-db-settings.png",n="/nada-documentation/images/nada3-to-4-upgrade.png",f=JSON.parse('{"title":"Upgrade from 3.x to 4.0","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/upgrade/upgrade-40.md","filePath":"installation-guide/upgrade/upgrade-40.md","lastUpdated":1786379412000}'),r={name:"installation-guide/upgrade/upgrade-40.md"};function d(p,e,l,u,c,g){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="upgrade-from-3-x-to-4-0" tabindex="-1">Upgrade from 3.x to 4.0 <a class="header-anchor" href="#upgrade-from-3-x-to-4-0" aria-label="Permalink to &quot;Upgrade from 3.x to 4.0&quot;">​</a></h1><p>For users with an existing NADA 3.x catalog an upgrade script is included that will update your NADA 3.x database to NADA 4.x. The process involves modifying your NADA 3.x database and thus carries some risks. The script will add new tables to the NADA 3.x database. All user accounts and survey information will be retained by the upgrade.</p><div class="tip custom-block"><p class="custom-block-title">Important</p><p>Backup the NADA 3.x database before doing anything!!</p></div><ol><li><p>Follow the instructions on page 4 and set up a folder in the web root containing the NADA 4 files.</p></li><li><p>Edit the database.php file as instructed in the section above: NADA database configurations for MySQL.</p></li><li><p>Instead of entering a new database name, user account name and password -fill in the details of the existing NADA 3.x database.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Note</p><p>These can be found by looking at the existing NADA 3.x database.php file and entering the settings into the NADA 4 database.php file.</p></div><p><img src="'+i+'" alt="Database settings"></p><ol start="4"><li><p>Save the file.</p></li><li><p>Navigate to the URL for the NADA4 site: Example: <a href="http://your-nada-site/nada4/index.php/nada4_upgrade" target="_blank" rel="noreferrer">http://your-nada-site/nada4/index.php/nada4_upgrade</a></p></li><li><p>The following page loads:</p></li></ol><p><img src="'+n+'" alt="Upgrade page"></p><p>Take note of the warnings and make any necessary corrections before</p><p>clicking the “Upgrade database to NADA 4” button.</p><div class="danger custom-block"><p class="custom-block-title">Warning</p><p>This step makes changes to your nada 3 database that are not undo-able so make sure you do make a database backup before this step.</p></div><p>Click on the “Upgrade database to NADA 4” button and wait for the page to reload. The output of the page will look something like below:</p><p>The script will print number of messages about failed table updates. This does not mean the script failed to upgrade. It just means some of the updates were not needed on your version of NADA 3. Different versions of NADA have different numbers of fields in the database and the upgrade script tries to fix the missing fields for all these different versions of NADA. If the existing NADA 3 database already has that field then it reports it as an error.</p><p>You can ignore the error messages that include the wording “Duplicate column name” or “Duplicate entry”.</p><p>Now your database has been migrated to NADA version 4.1.</p>',15)])])}const m=a(r,[["render",d]]);export{f as __pageData,m as default};
